-- Corrected query shape captured from GA4 Traffic Pages, parameterized for any property.
-- psql -v account_id=46 -v date_start=2025-01-01 -v date_end=2026-10-29 -v analyze=false
-- Default EXPLAIN does not execute the aggregation. Analyze mode is opt-in, read-only,
-- and limited to 45 seconds; run it only during a quiet period.
\if :{?analyze}
\else
\set analyze false
\endif
BEGIN READ ONLY;
SET LOCAL statement_timeout = '45s';
\if :analyze
EXPLAIN (ANALYZE, BUFFERS, SETTINGS, FORMAT TEXT)
\else
EXPLAIN (COSTS, VERBOSE, SETTINGS, FORMAT TEXT)
\endif
SELECT COALESCE(dv_dim_landing_page.value, 'unknown') AS "dimensions.landing_page", SUM(CASE WHEN LOWER(mc.name) IN ('screenpageviews') AND LOWER(mc.period) = 'daily' THEN m.value ELSE 0 END) AS "screenPageViews", SUM(CASE WHEN LOWER(mc.name) IN ('sessions') AND LOWER(mc.period) = 'daily' THEN m.value ELSE 0 END) AS "sessions", CASE WHEN SUM(CASE WHEN LOWER(mc.name) IN ('bouncerate', 'bounce_rate') AND LOWER(mc.period) = 'daily' AND (companion_0.observation_count IS NULL OR companion_0.observation_count <> 1 OR companion_0.weight_value IS NULL OR companion_0.weight_value < 0) THEN 1 ELSE 0 END) > 0 THEN NULL ELSE SUM(CASE WHEN LOWER(mc.name) IN ('bouncerate', 'bounce_rate') AND LOWER(mc.period) = 'daily' THEN m.value * companion_0.weight_value ELSE 0 END) / NULLIF(SUM(CASE WHEN LOWER(mc.name) IN ('bouncerate', 'bounce_rate') AND LOWER(mc.period) = 'daily' THEN companion_0.weight_value ELSE 0 END), 0) END AS "bounceRate", CASE WHEN SUM(CASE WHEN LOWER(mc.name) IN ('averagesessionduration', 'average_session_duration') AND LOWER(mc.period) = 'daily' AND (companion_0.observation_count IS NULL OR companion_0.observation_count <> 1 OR companion_0.weight_value IS NULL OR companion_0.weight_value < 0) THEN 1 ELSE 0 END) > 0 THEN NULL ELSE SUM(CASE WHEN LOWER(mc.name) IN ('averagesessionduration', 'average_session_duration') AND LOWER(mc.period) = 'daily' THEN m.value * companion_0.weight_value ELSE 0 END) / NULLIF(SUM(CASE WHEN LOWER(mc.name) IN ('averagesessionduration', 'average_session_duration') AND LOWER(mc.period) = 'daily' THEN companion_0.weight_value ELSE 0 END), 0) END AS "averageSessionDuration", CASE WHEN COUNT(DISTINCT CASE WHEN LOWER(mc.name) IN ('totalrevenue') AND LOWER(mc.period) = 'daily' THEN mc.channeled_account_id END) > 1 AND (COUNT(DISTINCT CASE WHEN LOWER(mc.name) IN ('totalrevenue') AND LOWER(mc.period) = 'daily' THEN NULLIF(TRIM(m.metadata #>> '{ga4_report_quality,currencyCode}'), '') END) <> 1 OR MAX(CASE WHEN LOWER(mc.name) IN ('totalrevenue') AND LOWER(mc.period) = 'daily' AND NULLIF(TRIM(m.metadata #>> '{ga4_report_quality,currencyCode}'), '') IS NULL THEN 1 ELSE 0 END) = 1) THEN 1 ELSE 0 END AS "_contract_currency_0", SUM(CASE WHEN LOWER(mc.name) IN ('totalrevenue') AND LOWER(mc.period) = 'daily' THEN m.value ELSE 0 END) AS "totalRevenue", SUM(CASE WHEN LOWER(mc.name) IN ('conversions') AND LOWER(mc.period) = 'daily' THEN m.value ELSE 0 END) AS "conversions" FROM metrics m JOIN metric_configs mc ON m.metric_config_id = mc.id LEFT JOIN dimension_set_items dsi_dim_landing_page ON mc.dimension_set_id = dsi_dim_landing_page.dimension_set_id AND dsi_dim_landing_page.dimension_value_id IN ( SELECT sub_dv.id FROM dimension_values sub_dv JOIN dimension_keys sub_dk ON sub_dv.dimension_key_id = sub_dk.id WHERE LOWER(sub_dk.name) = 'landing_page' ) LEFT JOIN dimension_values dv_dim_landing_page ON dsi_dim_landing_page.dimension_value_id = dv_dim_landing_page.id LEFT JOIN dimension_set_items dsi_dim_filter_scope ON mc.dimension_set_id = dsi_dim_filter_scope.dimension_set_id AND dsi_dim_filter_scope.dimension_value_id IN ( SELECT sub_dv.id FROM dimension_values sub_dv JOIN dimension_keys sub_dk ON sub_dv.dimension_key_id = sub_dk.id WHERE LOWER(sub_dk.name) = 'scope' ) LEFT JOIN dimension_values dv_dim_filter_scope ON dsi_dim_filter_scope.dimension_value_id = dv_dim_filter_scope.id LEFT JOIN (SELECT wc.channel, wc.account_id, wc.channeled_account_id, wc.campaign_id, wc.channeled_campaign_id, wc.channeled_ad_group_id, wc.channeled_ad_id, wc.creative_id, wc.event_id, wc.channeled_event_id, wc.page_id, wc.post_id, wc.product_id, wc.customer_id, wc.order_id, wc.query_id, wc.country_id, wc.device_id, wc.dimension_set_id, wc.location_id, wc.state_id, wc.city_id, wm.metric_date, COUNT(*) AS observation_count, MAX(wm.value) AS weight_value FROM metrics wm JOIN metric_configs wc ON wc.id = wm.metric_config_id WHERE LOWER(wc.name) IN ('sessions') AND LOWER(wc.period) = 'daily' AND wm.metric_date >= :'date_start' AND wm.metric_date <= :'date_end' AND wc.channeled_account_id = :'account_id' AND wc.channel IN (SELECT id FROM channels WHERE name IN ('google_analytics')) AND wc.dimension_set_id IN (SELECT wi.dimension_set_id FROM dimension_set_items wi JOIN dimension_values wv ON wv.id=wi.dimension_value_id JOIN dimension_keys wk ON wk.id=wv.dimension_key_id WHERE LOWER(wk.name)='scope' AND wv.value='traffic_matrix') GROUP BY wc.channel, wc.account_id, wc.channeled_account_id, wc.campaign_id, wc.channeled_campaign_id, wc.channeled_ad_group_id, wc.channeled_ad_id, wc.creative_id, wc.event_id, wc.channeled_event_id, wc.page_id, wc.post_id, wc.product_id, wc.customer_id, wc.order_id, wc.query_id, wc.country_id, wc.device_id, wc.dimension_set_id, wc.location_id, wc.state_id, wc.city_id, wm.metric_date) companion_0 ON companion_0.metric_date = m.metric_date AND LOWER(mc.name) IN ('averagesessionduration','average_session_duration','bouncerate','bounce_rate') AND COALESCE(companion_0.channel, 0) = COALESCE(mc.channel, 0) AND (companion_0.channel IS NULL) = (mc.channel IS NULL) AND COALESCE(companion_0.account_id, 0) = COALESCE(mc.account_id, 0) AND (companion_0.account_id IS NULL) = (mc.account_id IS NULL) AND COALESCE(companion_0.channeled_account_id, 0) = COALESCE(mc.channeled_account_id, 0) AND (companion_0.channeled_account_id IS NULL) = (mc.channeled_account_id IS NULL) AND COALESCE(companion_0.campaign_id, 0) = COALESCE(mc.campaign_id, 0) AND (companion_0.campaign_id IS NULL) = (mc.campaign_id IS NULL) AND COALESCE(companion_0.channeled_campaign_id, 0) = COALESCE(mc.channeled_campaign_id, 0) AND (companion_0.channeled_campaign_id IS NULL) = (mc.channeled_campaign_id IS NULL) AND COALESCE(companion_0.channeled_ad_group_id, 0) = COALESCE(mc.channeled_ad_group_id, 0) AND (companion_0.channeled_ad_group_id IS NULL) = (mc.channeled_ad_group_id IS NULL) AND COALESCE(companion_0.channeled_ad_id, 0) = COALESCE(mc.channeled_ad_id, 0) AND (companion_0.channeled_ad_id IS NULL) = (mc.channeled_ad_id IS NULL) AND COALESCE(companion_0.creative_id, 0) = COALESCE(mc.creative_id, 0) AND (companion_0.creative_id IS NULL) = (mc.creative_id IS NULL) AND COALESCE(companion_0.event_id, 0) = COALESCE(mc.event_id, 0) AND (companion_0.event_id IS NULL) = (mc.event_id IS NULL) AND COALESCE(companion_0.channeled_event_id, 0) = COALESCE(mc.channeled_event_id, 0) AND (companion_0.channeled_event_id IS NULL) = (mc.channeled_event_id IS NULL) AND COALESCE(companion_0.page_id, 0) = COALESCE(mc.page_id, 0) AND (companion_0.page_id IS NULL) = (mc.page_id IS NULL) AND COALESCE(companion_0.post_id, 0) = COALESCE(mc.post_id, 0) AND (companion_0.post_id IS NULL) = (mc.post_id IS NULL) AND COALESCE(companion_0.product_id, 0) = COALESCE(mc.product_id, 0) AND (companion_0.product_id IS NULL) = (mc.product_id IS NULL) AND COALESCE(companion_0.customer_id, 0) = COALESCE(mc.customer_id, 0) AND (companion_0.customer_id IS NULL) = (mc.customer_id IS NULL) AND COALESCE(companion_0.order_id, 0) = COALESCE(mc.order_id, 0) AND (companion_0.order_id IS NULL) = (mc.order_id IS NULL) AND COALESCE(companion_0.query_id, 0) = COALESCE(mc.query_id, 0) AND (companion_0.query_id IS NULL) = (mc.query_id IS NULL) AND COALESCE(companion_0.country_id, 0) = COALESCE(mc.country_id, 0) AND (companion_0.country_id IS NULL) = (mc.country_id IS NULL) AND COALESCE(companion_0.device_id, 0) = COALESCE(mc.device_id, 0) AND (companion_0.device_id IS NULL) = (mc.device_id IS NULL) AND COALESCE(companion_0.dimension_set_id, 0) = COALESCE(mc.dimension_set_id, 0) AND (companion_0.dimension_set_id IS NULL) = (mc.dimension_set_id IS NULL) AND COALESCE(companion_0.location_id, 0) = COALESCE(mc.location_id, 0) AND (companion_0.location_id IS NULL) = (mc.location_id IS NULL) AND COALESCE(companion_0.state_id, 0) = COALESCE(mc.state_id, 0) AND (companion_0.state_id IS NULL) = (mc.state_id IS NULL) AND COALESCE(companion_0.city_id, 0) = COALESCE(mc.city_id, 0) AND (companion_0.city_id IS NULL) = (mc.city_id IS NULL) WHERE mc.channel IN (SELECT id FROM channels WHERE name IN ('google_analytics')) AND m.metric_date >= :'date_start' AND m.metric_date <= :'date_end' AND mc.channeled_account_id = :'account_id' AND dv_dim_filter_scope.value = 'traffic_matrix' AND LOWER(mc.name) IN ('screenpageviews', 'sessions', 'bouncerate', 'bounce_rate', 'averagesessionduration', 'average_session_duration', 'totalrevenue', 'conversions') AND LOWER(mc.period) = 'daily' GROUP BY COALESCE(dv_dim_landing_page.value, 'unknown') ;
ROLLBACK;
